import{_ as n,C as i,c as r,o as l,aj as s,G as t,w as h}from"./chunks/framework.Bfdr4H5E.js";const v=JSON.parse('{"title":"Routines – Post-Session","description":"","frontmatter":{"outline":"deep","prev":{"text":"Routines – During Session","link":"/trading-with-pav/routines-during-session"},"next":{"text":"Contingency Management Procedures","link":"/trading-with-pav/contingency-management-procedures"}},"headers":[],"relativePath":"trading-with-pav/routines-post-session.md","filePath":"trading-with-pav/routines-post-session.md"}'),d={name:"trading-with-pav/routines-post-session.md"};function m(p,e,u,c,g,f){const a=i("GraphComment"),o=i("ClientOnly");return l(),r("div",null,[e[0]||(e[0]=s('<h1 id="routines-–-post-session" tabindex="-1">Routines – Post-Session <a class="header-anchor" href="#routines-–-post-session" aria-label="Permalink to &quot;Routines – Post-Session&quot;">​</a></h1><h3 id="immediately-after" tabindex="-1">Immediately After <a class="header-anchor" href="#immediately-after" aria-label="Permalink to &quot;Immediately After&quot;">​</a></h3><ul><li><ol><li>Relaxation and Breathing Session (quick – 2 to 3 minutes max)</li></ol></li><li><ol start="2"><li>Administration (approx. 5 mins)</li></ol><ul><li>a) Export transactions from broker</li><li>b) Confirm my trade log matches the broker’s transactions</li><li>c) Complete any post-session trading log and spreadsheet entries</li><li>d) Print charts and mark the trades (usually completed during session, if it allows time)</li><li>e) Review P&amp;L</li><li>f) Update calendar with Green/Red profit or loss indicator</li></ul></li><li><ol start="3"><li>Trading Session Review (approx. 45 mins+; document any significant findings in the Trading Log under the heading Trading Session Review)</li></ol><ul><li>a) Market Environment Review <ul><li>i) With hindsight, how would you define the market environment?</li><li>ii) How successful were you in identifying the market environment during the trading session?</li><li>iii) What signs were present to indicate this environment?</li><li>iv) What key pattern features were present and how could they have been used to identify the market trend and bias?</li><li>v) Step manually through the chart bar by bar, or use a market replay feature to step through the chart at high speed, observing the market environment and the signals that identify that environment, trend and bias.</li><li>vi) Print the chart and add appropriate notes to your Market Structure Journal.</li></ul></li><li>b) Trades Taken <ul><li>i) With the benefit of hindsight, was your trade based on a valid setup for that market environment?</li><li>ii) If this was a valid trade: <ul><li>(1) Review the signals that led you to identify the trade opportunity?</li><li>(2) What was the ideal entry point? How does that compare to your entry? What signals (if any) did the market provide, which could have led to an improved entry?</li><li>(3) Was the initial stop location appropriate? Was it in accordance with your trading plan? Where, with the benefit of hindsight, should the stop have been placed? What signals (if any) did the market provide to identify that location?</li><li>(4) What was the optimal trade management strategy, in order to minimize risk when wrong or maximize gain when right? How does that compare to your trade management strategy? What signals (if any) did the market provide for moving the stop to breakeven, or beyond?</li><li>(5) What was the optimal exit location or locations, in order to minimize risk when wrong or maximize gain when right? How does this compare to your exit location? What signals (if any) did the market provide to identify this ideal exit location?</li></ul></li><li>iii) If this was not a valid trade: <ul><li>(1) What signals were present that should have led you to avoid that trade?</li><li>(2) Having got into the trade, was the initial stop location appropriate? Was it in accordance with my trading plan? Where, with the benefit of hindsight, should the stop have been placed? What signals (if any) did the market provide to identify that location?</li><li>(3) What was the optimal way to manage this trade, in order to minimize risk when wrong or maximize gain when right? How does that compare to your trade management strategy? What signals (if any) did the market provide for moving the stop to breakeven, or beyond?</li><li>(4) What was the optimal exit location or locations, in order to minimize risk when wrong or maximize gain when right? How does this compare to your exit location? What signals (if any) did the market provide to identify this ideal exit location?</li></ul></li><li>iv) Replay that portion of the trading session, making optimal decisions for valid trades and avoiding invalid trades, either by stepping manually through the chart bar by bar, or use a market replay feature.</li></ul></li><li>c) Trades Missed <ul><li>i) With the benefit of hindsight, where were the valid trade opportunities that were missed?</li><li>ii) For each of these trade opportunities: <ul><li>(1) What signals did the market provide that should have alerted me to the trade setup?</li><li>(2) What was the ideal entry point? What signals (if any) did the market provide, which could have led to identify this ideal entry?</li><li>(3) Where, with the benefit of hindsight, should the stop have been placed? What signals (if any) did the market provide to identify that location?</li><li>(4) What was the optimal trade management strategy, in order to minimize risk when wrong or maximize gain when right? What signals (if any) did the market provide for moving the stop to breakeven, or beyond?</li><li>(5) What was the optimal exit location or locations, in order to minimize risk when wrong or maximize gain when right? What signals (if any) did the market provide to identify these ideal exit locations?</li></ul></li><li>iii) Replay the trade, making optimal decisions, either by stepping manually through the chart bar by bar, or use a market replay feature.</li></ul></li><li>d) Summarize this session’s performance in the trading log.</li></ul></li><li><ol start="4"><li>Physical and Psychological Performance Review (approx. 2-3 mins; document any observations in my trading log under the heading Performance Review)</li></ol><ul><li>a) Were my fatigue levels appropriately managed?</li><li>b) Was I in optimal physical condition? What can I do to improve?</li><li>c) Was my ability to sustain focus at an acceptable level? What can I do to improve?</li><li>d) Was I accepting of emotion during the trading session, without letting it unduly influence decision making? What can I do to improve?</li><li>e) Was my mental state during trade execution one of confidence and self-belief, or one of fear? Why? What can I do to improve?</li><li>f) Am I satisfied with my performance during this trading session? What can I do to improve?</li><li>g) Do I feel I am making progress in my trading performance from day to day? What can I improve?</li><li>h) Write summary notes.</li></ul></li><li><ol start="5"><li>Next Session Preparation (approx. 2 to 3 mins; document in my trading log under the heading Next Session)</li></ol><ul><li>a) Document any goals for the next session</li></ul></li><li><ol start="6"><li>Final Relaxation and Breathing Session (quick – 2 to 3 minutes max)</li></ol></li><li><ol start="7"><li>Completely let go of whatever happened during the trading session</li></ol></li></ul><h3 id="before-bed" tabindex="-1">Before Bed <a class="header-anchor" href="#before-bed" aria-label="Permalink to &quot;Before Bed&quot;">​</a></h3><ol><li>Relaxation and Breathing Session (quick – 2 to 3 minutes max)</li><li>Visualization of success – achievement of my outcome goals</li><li>Completely let go of whatever happened during the day</li></ol><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',6)),t(o,null,{default:h(()=>[t(a)]),_:1})])}const w=n(d,[["render",m]]);export{v as __pageData,w as default};
